\label{thm:multipoint}
For every $c\ge0$, $t\ge0$, initial profile $h\in\widehat{\mathcal X}$ as defined in \eqref{eqn:state-space}, and the observation point \(0\leq x_1<\cdots<x_n\) and \(r_1,\ldots,r_n \in \mathbb{Z}\),
\begin{equation}\label{eq:multi-result}
 \mathbb P_h^c\bigl(h(t,x_j)\le r_j,\ 1\le j\le n\bigr)
 =\widehat F_n(t,h)=\operatorname{Pf}(J+JK(t,h)).
\end{equation}

\label{prop:trace-class}
      Let $M_\eta f(u)=e^{\eta u}f(u)$ and \( 0\leq c<C_0\) for some constant \(C_0\), choose
\begin{equation}\label{eq:weights}
 \omega=\log\max(1,C_0)<\eta_1<\cdots<\eta_n,\qquad
 \mathcal M_i=\operatorname{diag}(M_{\eta_i},M_{-\eta_i}),\qquad
 \mathcal M=\operatorname{diag}(\mathcal M_1,\ldots,\mathcal M_n).
\end{equation}
Define the conjugated kernel by
\begin{equation}\label{eq:weighted-kernels}
 A:=\mathcal M(JK)\mathcal M.
\end{equation}
For $h\in\widehat{\mathcal X}$, \(A\) is a trace-class operator, so the Fredholm Pfaffian is well-defined.

\label{def:regular}
For the fixed positions \(\boldsymbol x = (x_1,\ldots,x_n)\), let $\mathcal R_{\boldsymbol x}$
be the set of pairs $(t,h)$ with $t>0$ and $h\in\widehat{\mathcal X}_{\mathrm{fin}}$
satisfying the following conditions on $[0,x_n+t]$.
\begin{enumerate}
      \item \(h\) has no jump at $|t-x_j|$, $t+x_j$ or \(0\);
      \item \(t\ne x_j,\qquad 2t\ne|x_i-x_j|\ (i\ne j),\qquad
 2t\ne x_i+x_j\quad(1\le i,j\le n)\).
 \item \(h\) has no isolated peak, i.e., \(h(z)=\max\{h(z^+),h(z^-)\}\).
\end{enumerate}

\label{lem:firsthit}
For $h\in\widehat{\mathcal X}_{\mathrm{fin}}$, $0\le a\le b$, and $z\in[a,b]$,
\begin{equation}\label{eq:first-hit-change}
 P_{a,b}^{C_zh}-P_{a,b}^h
  =Q_{a,z}^h(\delta_{h(z)+1}\otimes\delta_{h(z)+1})Q_{z,b}^h.
\end{equation}
At the endpoints,
\begin{equation}\label{eq:first-hit-endpoints}
 \begin{split}
 P_{a,b}^{C_ah}-P_{a,b}^h
   &=\delta_{h(a)+1}\otimes Q_{a,b}^h(h(a)+1,\cdot),\\
 P_{a,b}^{C_bh}-P_{a,b}^h
   &=Q_{a,b}^h(\cdot,h(b)+1)\otimes\delta_{h(b)+1}.
 \end{split}
\end{equation}

\label{prop:rank-two}
For $z\in[0,\infty)$, $p,q\neq 0$, define \(a_z:=Q_{0,z}^h\delta_{h(z)+1}\) and define
$\beta_p$ and $u_p$ by
\[
 \begin{split}
 \beta_p&=
 \begin{cases}
  \delta_{h(z)+1}Q_{z,p}^he^{-p\Delta}H_-^{-1},&p>0,\ z\le p,\\
  0,&\text{otherwise},
 \end{cases}\\
 u_p&=
 \begin{cases}
  (I+T_p^*H)Q_{0,z}^h\delta_{h(z)+1},&p>0,\\
  e^{-p\Delta}Q_{-p,z}^h\delta_{h(z)+1},&p<0,\ -p\le z,\\
  0,&p<0,\ z<-p.
 \end{cases}
 \end{split}
\]
Then,
\begin{equation}\label{eq:rank-two-W}
 \delta_zW_{p,q}=u_p\otimes\beta_q-\beta_p\otimes u_q.
\end{equation}

\label{prop:hit-generator}
Let $0\le a<b$. Suppose \(h\in \widehat{\mathcal X}_{\mathrm{fin}}\) has no jump at \(a,b\) and \(h\) has no isolated peaks, i.e. \(h(z) = \max\{h(z^-),h(z^+)\}\). For every $c\ge0$ and $a>0$,
\begin{equation}\label{eq:LP-interior}
 \mathcal L_c P_{a,b}^h=2[P_{a,b}^h,\nabla]+\mathcal E_a+\mathcal E^b.
\end{equation}
For $a=0$,
\begin{equation}\label{eq:LP-origin}
 \mathcal L_c P_{0,b}^h
 =2[P_{0,b}^h,\nabla]+(I-c\tau_-)\mathcal E_0+\mathcal E^b.
\end{equation}
Here $[A,B]=AB-BA$. Jump sizes need not be one.

\label{prop:moving-endpoints}
Assume $h$ is fixed and it is constant near the positive endpoints
of $0\le a<b$. Then
\begin{equation}\label{eq:endpoint-single}
 -\partial_aP_{a,b}-\Delta P_{a,b}=-\mathcal E_a
 \quad(a>0),\qquad
 \partial_bP_{a,b}-P_{a,b}\Delta=-\mathcal E^b.
\end{equation}
Consequently, along differentiable endpoints $0<a(t)<b(t)$,
\begin{equation}\label{eq:moving-hit-chain-rule}
 \frac{d}{dt}P_{a(t),b(t)}^h
 =-a'(t)\Delta P_{a,b}^h+b'(t)P_{a,b}^h\Delta
       +a'(t)\mathcal E_a-b'(t)\mathcal E^b.
\end{equation}
If $a=0$, only the terms containing $b'$ remain.

\label{prop:folded-residual}
Let $0\le c<1$ and let $p,q\ne0$ vary with $p'(t)=q'(t)=1$. Suppose \(h\in \widehat{\mathcal X}_{\mathrm{fin}}\) has no jump at \(a,b\) and \(h\) has no isolated peaks, i.e. \(h(z) = \max\{h(z^-),h(z^+)\}\). For $b>0$, define
\begin{equation}\label{eq:OD}
 \mathcal D_b:=\mathcal E^b e^{-b\Delta}H_-^{-1}
 =-\bigl(Q_{0,b}^h\delta_{h(b)+1}\bigr)\otimes
       \bigl(\delta_{h(b)}e^{-b\Delta}H_-^{-1}\bigr).
\end{equation} Then
\begin{equation}\label{eq:folded-residual}
 \mathscr D W_{p,q}=
 \begin{cases}
 -2\bigl[(I+T_p^*H)\mathcal D_q+\mathcal D_p^*(HT_q-I)\bigr],
       &p,q>0,\\[2pt]
 -2e^{-p\Delta}(\mathcal E_{-p}+\mathcal E_q)e^{-q\Delta}H_-^{-1},
       &p<0<q\\[2pt]
 2\bigl[e^{-q\Delta}(\mathcal E_{-q}+\mathcal E_p)
                           e^{-p\Delta}H_-^{-1}\bigr]^*,
       &q<0<p\\[2pt]
 0,    &p,q<0.
 \end{cases}
\end{equation}

\label{prop:projected}
Let $0\le c<1$. At every
$(t,h)\in\mathcal R_{\boldsymbol x}\cap\mathcal A_{\boldsymbol r}$,
\begin{equation}\label{eq:projected}
 (\partial_t-\mathcal L_c)K_{ij}(t,h)=0\qquad(1\le i,j\le n).
\end{equation}
Here $K_{ij}=R_{ij}+\widetilde K_{ij}$ includes the threshold
projections in \eqref{eq:skew-kernel}.

\label{thm:FV}
For $0\le c<1$, $t>0$, and $h\in\widehat{\mathcal X}_{\mathrm{fin}}$,
\begin{equation}\label{eq:FV}
 (t,h)\notin\mathcal A_{\boldsymbol r}
 \quad\Longrightarrow\quad
 \widehat F_n(t,h)=0.
\end{equation}

\label{lem:coupled-lifting}
If $\mathscr Bf=0$, then
\begin{equation}\label{eq:full-null-from-auxiliary}
 (I+K)F=0.
\end{equation}

\label{prop:auxiliary-null}
For $\mathscr B$ defined by
\eqref{eq:coupled-other-first}--\eqref{eq:coupled-other-last},
\begin{equation}\label{eq:auxiliary-null-dimension}
 \dim\ker\mathscr B\ge\ell-r_k>0.
\end{equation}

Proposition~\ref{prop:auxiliary-null} and Lemma~\ref{lem:coupled-lifting}
give $(I+K)F=0$ for the vector in
\eqref{eq:coupled-embedding}. Thus, the Pfaffian is \(0\).

\label{lem:cluster}
Suppose $1\le k<n$ and $x_{k+1}-x_{k}>2t$. Put
$I_L=\{1,\ldots,k\}$ and $I_R=\{k+1,\ldots,n\}$. Then
\begin{equation}\label{eq:separated-factorization}
 \widehat F_n(t,h)=\widehat F(t,h;I_L)D(t,h;I_R).
\end{equation}
Whenever \(t<x_i\) for all \(i\),
$\widehat F(t,h;I)=D(t,h;I)$.

\label{thm:initial}
For $0\le c<1$ and every $h\in\widehat{\mathcal X}_{\mathrm{fin}}$,
\begin{equation}\label{eq:init-result}
 \lim_{t\downarrow0}\widehat F_n(t,h)
 =\prod_{j=1}^n\mathbf1_{\{h(x_j)\le r_j\}}.
\end{equation}

\label{thm:uniform}
For fixed $T,\boldsymbol x,\boldsymbol r$ and $0\le c<1$, there is
$C<\infty$ independent of \(t,h\) such that
\begin{equation}\label{eq:uniform-F}
 |\widehat F_n(t,h)|\le C\qquad
       (0\le t\le T,\ h\in\widehat{\mathcal X}_{\mathrm{fin}}).
\end{equation}

\label{prop:mild-unique}
For every bounded Borel function $f$ on $\widehat{\mathcal X}_B$ and every $c\ge0$,
the function $U(t,h)=\mathbb E_h^{B,c}[f(h^B(t;h))]$ is the unique
bounded Borel solution on $[0,T]\times\widehat{\mathcal X}_B$ of
\begin{equation}\label{eq:mild}
 \begin{split}
 U(t,h)={}&e^{-\lambda_Bt}f(\phi_t^B h)+\int_0^t e^{-\lambda_Bs}
      \int_{[0,B)}U(t-s,C_z\phi_s^B h)\,\mu_B(dz)\,ds.
 \end{split}
\end{equation}
Boundedness means a single bound over both time and the entire profile
space.

\label{lem:tails}
For every $\lambda>0$ and $T,B<\infty$, there is a finite constant
such that each kernel
\[
 D\in\{S_{t,x},\ e^{x\Delta},\ L_+(t),\ L_-(t)\},
 \qquad |t|\le T,\quad |x|\le B,
\]
satisfies
\begin{equation}\label{eq:free-tail}
 \sup_u\sum_v|D(u,v)|e^{\lambda|u-v|}
 +\sup_v\sum_u|D(u,v)|e^{\lambda|u-v|}<\infty,
\end{equation}
uniformly over \(t,x\). The factors are defined in
\eqref{eq:free} and \eqref{eq:Lpm}.

For $0\le a\le b\le B$,
\begin{align}
 P_{a,b}^h(u,v)&\le C_{\lambda,B}
 e^{-\lambda((u-h_*)_++(v-h_*)_++|u-v|)},\label{eq:hit-tail}\\
 \sum_{w\ge v}P_{a,b}^h(u,w)&\le C_{\lambda,B}
 e^{-\lambda((u-h_*)_++(v-h_*)_++(v-u)_+)},
 \label{eq:hit-cumulative}
\end{align}
with $C_{\lambda,B}=\exp\{2B(e^{2\lambda}-1)\}$.
The bounds include $a=b$ under the closed-interval convention.

\label{cor:everythingtrueintracenorm}
For \((t,h)\in \mathcal{R}_{\boldsymbol{x}}\), let \(A(t,h):=\mathcal{M}JK(t,h)\mathcal{M}\).
\begin{enumerate}
      \item \(A(t,h)\) is differentiable in the trace norm.
      \item \(A(t,C_zh)-A(t,h)\) is integrable in trace norm over interval \([0,\infty)\).
\end{enumerate}
